// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";

interface IBiggiBuybackAgent {
    function setRouter(address router_) external;
    function setTreasury(address treasury_) external;
    function setPolicy(address policy_) external;
    function setDripLM(address dripLM_) external;
    function setSwapPath(address[] calldata newPath) external;
    function clearSwapPath() external;
    function setFallbacks(uint256 slipBps, uint256 deadlineSec, uint256 cooldownSec) external;
    function toggleAutoBuyback(bool enabled) external;
}

interface IBiggiDripLiquidityManager {
    function setRouter(address r) external;
    function setReserve(address r) external;
    function setDripDistributor(address d) external;
    function setBuybackAgent(address a) external;
    function setSellPct(uint8 pct) external;
    function setSlippageBps(uint256 bps) external;
    function setTxDeadlineSec(uint256 sec_) external;
}

interface IDripDistributorSetup {
    function setDripLM(address lm) external;
    function setTreasury(address t) external;
    function setTokensPerMintOperator(address op) external;
    function setTokensPerMint(uint256 v) external;
    function setCollection(address coll, bool allowed) external;
}

interface IBiggiTokenSupplySetup {
    function setSupplyController(address c) external;
}

interface IBiggiSupplyControllerSetup {
    function setPair(address pair_) external;
    function snapshotBaseline() external;
}

contract BiggiBuybackDripSetup is Ownable {
    address public immutable buybackAgent;
    address public immutable dripLM;
    address public immutable dripDistributor;
    address public immutable reserveAddr;
    address public immutable treasuryAddr;
    address public immutable routerAddr;
    address public immutable policyAddr;

    address public tokenAddr;
    address public supplyController;
    bool public executed;

    event BranchSetupExecuted(address indexed buybackAgent, address indexed dripLM, address indexed dripDistributor);
    event SupplyTargetsSet(address indexed token, address indexed supplyController);
    event SupplyControllerWired(address indexed token, address indexed supplyController);
    event SupplyControllerPairConfigured(address indexed pair, bool baselineSnapshotted);

    constructor(address initialOwner,address buybackAgent_,address dripLM_,address dripDistributor_,address reserveAddr_,address treasuryAddr_,address routerAddr_,address policyAddr_) Ownable(initialOwner) {
        require(initialOwner != address(0), "owner=0");
        require(buybackAgent_ != address(0), "buyback=0");
        require(dripLM_ != address(0), "dripLM=0");
        require(dripDistributor_ != address(0), "dripD=0");
        require(reserveAddr_ != address(0), "reserve=0");
        require(treasuryAddr_ != address(0), "treasury=0");
        require(routerAddr_ != address(0), "router=0");
        buybackAgent = buybackAgent_; dripLM = dripLM_; dripDistributor = dripDistributor_; reserveAddr = reserveAddr_; treasuryAddr = treasuryAddr_; routerAddr = routerAddr_; policyAddr = policyAddr_;
    }

    function setupBuybackCore() public onlyOwner {
        IBiggiBuybackAgent B = IBiggiBuybackAgent(buybackAgent);
        B.setRouter(routerAddr);
        B.setTreasury(treasuryAddr);
        B.setPolicy(policyAddr);
        B.setDripLM(dripLM);
    }

    function configureBuybackSwapAndFallbacks(address[] calldata path,uint256 slipBps,uint256 deadline,uint256 cooldown,bool autoEnable) public onlyOwner {
        IBiggiBuybackAgent B = IBiggiBuybackAgent(buybackAgent);
        if (path.length == 0) B.clearSwapPath(); else B.setSwapPath(path);
        B.setFallbacks(slipBps, deadline, cooldown);
        B.toggleAutoBuyback(autoEnable);
    }

    function setupDripLMCore() public onlyOwner {
        IBiggiDripLiquidityManager D = IBiggiDripLiquidityManager(dripLM);
        D.setRouter(routerAddr); D.setReserve(reserveAddr); D.setDripDistributor(dripDistributor); D.setBuybackAgent(buybackAgent);
    }

    function configureDripLMParams(uint8 sellPct,uint256 slipBps,uint256 deadline) public onlyOwner {
        IBiggiDripLiquidityManager D = IBiggiDripLiquidityManager(dripLM);
        D.setSellPct(sellPct); D.setSlippageBps(slipBps); D.setTxDeadlineSec(deadline);
    }

    function setupDripDistributorCore(address treasury,uint256 tokensPerMint) public onlyOwner {
        require(treasury != address(0), "treasury=0");
        IDripDistributorSetup DD = IDripDistributorSetup(dripDistributor);
        DD.setTreasury(treasury);
        DD.setDripLM(dripLM);
        DD.setTokensPerMintOperator(dripLM);
        DD.setTokensPerMint(tokensPerMint);
    }

    function setSupplyTargets(address token_, address supplyController_) external onlyOwner {
        require(token_ != address(0), "token=0"); require(supplyController_ != address(0), "supply=0");
        tokenAddr = token_; supplyController = supplyController_; emit SupplyTargetsSet(token_, supplyController_);
    }

    function setupSupplyControllerCore() public onlyOwner {
        require(tokenAddr != address(0) && supplyController != address(0), "supply targets missing");
        IBiggiTokenSupplySetup(tokenAddr).setSupplyController(supplyController);
        emit SupplyControllerWired(tokenAddr, supplyController);
    }

    function configureSupplyControllerPair(address pair, bool snapshotBaseline_) public onlyOwner {
        require(supplyController != address(0), "supply=0"); require(pair != address(0), "pair=0");
        IBiggiSupplyControllerSetup(supplyController).setPair(pair);
        if (snapshotBaseline_) IBiggiSupplyControllerSetup(supplyController).snapshotBaseline();
        emit SupplyControllerPairConfigured(pair, snapshotBaseline_);
    }

    function runAll(address[] calldata buybackPath,uint256 buybackSlipBps,uint256 buybackDeadline,uint256 buybackCooldown,bool autoEnable,uint8 dripSellPct,uint256 dripSlippage,uint256 dripDeadline,address treasuryForDrip,uint256 tokensPerMint) external onlyOwner {
        require(!executed, "already executed");
        setupBuybackCore();
        configureBuybackSwapAndFallbacks(buybackPath, buybackSlipBps, buybackDeadline, buybackCooldown, autoEnable);
        setupDripLMCore();
        configureDripLMParams(dripSellPct, dripSlippage, dripDeadline);
        setupDripDistributorCore(treasuryForDrip, tokensPerMint);
        executed = true;
        emit BranchSetupExecuted(buybackAgent, dripLM, dripDistributor);
    }

    function runAllAndWireSupply(address[] calldata buybackPath,uint256 buybackSlipBps,uint256 buybackDeadline,uint256 buybackCooldown,bool autoEnable,uint8 dripSellPct,uint256 dripSlippage,uint256 dripDeadline,address treasuryForDrip,uint256 tokensPerMint,address tokenForSupply,address supplyController_,address pairForSupply,bool snapshotSupplyBaseline) external onlyOwner {
        require(!executed, "already executed");
        tokenAddr = tokenForSupply; supplyController = supplyController_; emit SupplyTargetsSet(tokenForSupply, supplyController_);
        setupBuybackCore();
        configureBuybackSwapAndFallbacks(buybackPath, buybackSlipBps, buybackDeadline, buybackCooldown, autoEnable);
        setupDripLMCore();
        configureDripLMParams(dripSellPct, dripSlippage, dripDeadline);
        setupDripDistributorCore(treasuryForDrip, tokensPerMint);
        setupSupplyControllerCore();
        if (pairForSupply != address(0)) configureSupplyControllerPair(pairForSupply, snapshotSupplyBaseline);
        executed = true;
        emit BranchSetupExecuted(buybackAgent, dripLM, dripDistributor);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

import "./Library/BiggiErrorsLib.sol";
import "./Library/BiggiCapsLib.sol";

/// @notice Účetní kontrakt držící BIGGI pro DripLM.
/// - CAP nezávislý na treasury (DRIP_DISTRIBUTOR_CAP)
/// - whitelist kolekcí pro notifyMint (accounting)
contract BiggiDripDistributor is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    IERC20 public immutable BIGGI;

    address public dripLM;
    address public treasury;

    // volitelný operator (např. DripLM), který může dynamicky přepisovat tokensPerMint
    address public tokensPerMintOperator;

    // kolik BIGGI (raw) se účetně alokuje za 1 mint
    uint256 public tokensPerMint;

    // účetní stav (claimovatelné)
    uint256 public availableTokens;

    // kumulativní statistiky
    uint256 public totalReceived;
    uint256 public totalClaimed;
    uint256 public totalNotified;
    bool public historicalStateSeeded;

    uint256 public constant CAP = BiggiCapsLib.DRIP_DISTRIBUTOR_TOTAL_CAP;

    mapping(address => bool) public collections;

    /* ===== events ===== */
    event CollectionSet(address indexed coll, bool allowed);
    event DripLMSet(address indexed oldLM, address indexed newLM);
    event TreasurySet(address indexed oldT, address indexed newT);
    event TokensPerMintOperatorSet(address indexed oldOp, address indexed newOp);
    event TokensPerMintSet(uint256 oldVal, uint256 newVal);

    event NotifyMint(address indexed coll, uint256 count, uint256 tokensAdded);
    event Claimed(address indexed to, uint256 amount);

    event TopUp(address indexed from, uint256 amount);
    event NotifyTokenMint(address indexed tokenContract, uint256 amount);
    event HistoricalStateSeeded(
        uint256 totalReceived,
        uint256 totalClaimed,
        uint256 totalNotified,
        uint256 availableTokens
    );

    event RescueERC20(address token, address to, uint256 amount);
    event RescueNative(address to, uint256 amount);

    modifier onlyDripLM() {
        if (msg.sender != dripLM) revert BiggiErrorsLib.OnlyDripLM();
        _;
    }

    modifier onlyTreasury() {
        if (msg.sender != treasury) revert BiggiErrorsLib.OnlyTreasury();
        _;
    }

    constructor(address token_, address initialOwner) Ownable(initialOwner) {
        if (token_ == address(0) || initialOwner == address(0)) {
            revert BiggiErrorsLib.ZeroAddress();
        }
        BIGGI = IERC20(token_);
    }

    /* ===== admin setters ===== */

    function syncAvailableToBalance() external onlyOwner whenNotPaused {
        uint256 bal = BIGGI.balanceOf(address(this));
        availableTokens = bal;
    }

    function setCollection(address coll, bool allowed) external onlyOwner {
        if (coll == address(0)) revert BiggiErrorsLib.ZeroAddress();
        collections[coll] = allowed;
        emit CollectionSet(coll, allowed);
    }

    function setDripLM(address lm) external onlyOwner {
        if (lm == address(0)) revert BiggiErrorsLib.ZeroAddress();
        emit DripLMSet(dripLM, lm);
        dripLM = lm;
    }

    function setTreasury(address t) external onlyOwner {
        if (t == address(0)) revert BiggiErrorsLib.ZeroAddress();
        emit TreasurySet(treasury, t);
        treasury = t;
    }

    function setTokensPerMintOperator(address op) external onlyOwner {
        emit TokensPerMintOperatorSet(tokensPerMintOperator, op);
        tokensPerMintOperator = op;
    }

    /// @notice Owner nastaví tokensPerMint v raw jednotkách (např. 1000 * 1e18)
    function setTokensPerMint(uint256 v) external onlyOwner {
        emit TokensPerMintSet(tokensPerMint, v);
        tokensPerMint = v;
    }

    /// @notice Operator (např. DripLM) může dynamicky přepsat tokensPerMint podle buybacku
    function setTokensPerMintFromOperator(uint256 v) external {
        require(msg.sender == tokensPerMintOperator, "not operator");
        emit TokensPerMintSet(tokensPerMint, v);
        tokensPerMint = v;
    }

    function seedHistoricalState(
        uint256 totalReceived_,
        uint256 totalClaimed_,
        uint256 totalNotified_,
        uint256 availableTokens_
    ) external onlyOwner {
        require(!historicalStateSeeded, "already seeded");
        totalReceived = totalReceived_;
        totalClaimed = totalClaimed_;
        totalNotified = totalNotified_;
        availableTokens = availableTokens_;
        historicalStateSeeded = true;
        emit HistoricalStateSeeded(totalReceived_, totalClaimed_, totalNotified_, availableTokens_);
    }

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    /* ===== notify from collection (accounting only) ===== */
    function notifyMint(uint256 mintedCount) external nonReentrant whenNotPaused {
        if (mintedCount == 0) revert BiggiErrorsLib.AmountZero();
        if (!collections[msg.sender]) revert BiggiErrorsLib.NotWhitelistedCollection();

        uint256 add = tokensPerMint * mintedCount;
        availableTokens += add;
        totalNotified += add;

        emit NotifyMint(msg.sender, mintedCount, add);
    }

    /* ===== token contract notification (initial/top-up) ===== */
    function notifyTokenMint(uint256 amount) external nonReentrant whenNotPaused {
        if (amount == 0) revert BiggiErrorsLib.AmountZero();
        if (msg.sender != address(BIGGI)) revert BiggiErrorsLib.OnlyToken();
        if (totalReceived + amount > CAP) revert BiggiErrorsLib.CapExceeded();

        uint256 netHeld = totalReceived >= totalClaimed ? (totalReceived - totalClaimed) : 0;
        uint256 bal = BIGGI.balanceOf(address(this));
        require(bal >= netHeld + amount, "token not transferred");

        totalReceived += amount;
        availableTokens += amount;

        emit NotifyTokenMint(msg.sender, amount);
        emit TopUp(msg.sender, amount);
    }

    /* ===== treasury deposit (TopUp) ===== */
    function depositTokens(uint256 amount) external nonReentrant whenNotPaused onlyTreasury {
        if (amount == 0) revert BiggiErrorsLib.AmountZero();
        if (totalReceived + amount > CAP) revert BiggiErrorsLib.CapExceeded();

        BIGGI.safeTransferFrom(msg.sender, address(this), amount);

        totalReceived += amount;
        availableTokens += amount;

        emit TopUp(msg.sender, amount);
    }
    // supply-controller top-ups are routed through BIGGI.notifyTokenMint(amount)

    /* ===== claim by DripLM ===== */
    function claim(uint256 amountRequested) external nonReentrant onlyDripLM whenNotPaused {
        if (amountRequested == 0) revert BiggiErrorsLib.AmountZero();

        uint256 bal = BIGGI.balanceOf(address(this));
        uint256 toSend = amountRequested;

        if (toSend > availableTokens) toSend = availableTokens;
        if (toSend > bal) toSend = bal;

        if (toSend == 0) revert BiggiErrorsLib.NoneAvailable();

        availableTokens -= toSend;
        totalClaimed += toSend;

        BIGGI.safeTransfer(msg.sender, toSend);
        emit Claimed(msg.sender, toSend);
    }

    function claimTo(address to, uint256 amountRequested) external nonReentrant onlyDripLM whenNotPaused {
        if (to == address(0)) revert BiggiErrorsLib.ToZero();
        if (amountRequested == 0) revert BiggiErrorsLib.AmountZero();

        uint256 bal = BIGGI.balanceOf(address(this));
        uint256 toSend = amountRequested;

        if (toSend > availableTokens) toSend = availableTokens;
        if (toSend > bal) toSend = bal;

        if (toSend == 0) revert BiggiErrorsLib.NoneAvailable();

        availableTokens -= toSend;
        totalClaimed += toSend;

        BIGGI.safeTransfer(to, toSend);
        emit Claimed(to, toSend);
    }

    /* ===== rescue & helpers ===== */
    function rescueERC20(address token, address to, uint256 amount) external onlyOwner {
        if (to == address(0)) revert BiggiErrorsLib.ToZero();
        IERC20(token).safeTransfer(to, amount);
        emit RescueERC20(token, to, amount);
    }

    function rescueNative(address payable to, uint256 amount) external onlyOwner {
        if (to == address(0)) revert BiggiErrorsLib.ToZero();
        (bool ok, ) = to.call{value: amount}("");
        require(ok, "native xfer fail");
        emit RescueNative(address(to), amount);
    }

    receive() external payable {}

    /* ===== view helpers ===== */

    function biggiBalance() public view returns (uint256) {
        return BIGGI.balanceOf(address(this));
    }

    function effectiveAvailable() public view returns (uint256) {
        uint256 bal = BIGGI.balanceOf(address(this));
        return availableTokens <= bal ? availableTokens : bal;
    }

    function getAvailable() external view returns (uint256) { return availableTokens; }
    function getTotalNotified() external view returns (uint256) { return totalNotified; }
    function getTotalClaimed() external view returns (uint256) { return totalClaimed; }
    function getTotalReceived() external view returns (uint256) { return totalReceived; }
    function isCollection(address a) external view returns (bool) { return collections[a]; }

    function capRemaining() external view returns (uint256) {
        if (totalReceived >= CAP) return 0;
        return CAP - totalReceived;
    }

    struct Snapshot {
        address token;
        address dripLM;
        address treasury;
        address operator;
        uint256 tokensPerMint;
        uint256 available;
        uint256 effectiveAvailable;
        uint256 totalReceived;
        uint256 totalClaimed;
        uint256 totalNotified;
        uint256 cap;
        uint256 capRemaining;
        uint256 balance;
        bool paused;
    }

    function snapshot() external view returns (Snapshot memory s) {
        s.token = address(BIGGI);
        s.dripLM = dripLM;
        s.treasury = treasury;
        s.operator = tokensPerMintOperator;
        s.tokensPerMint = tokensPerMint;

        s.available = availableTokens;

        uint256 bal = BIGGI.balanceOf(address(this));
        s.balance = bal;
        s.effectiveAvailable = availableTokens <= bal ? availableTokens : bal;

        s.totalReceived = totalReceived;
        s.totalClaimed = totalClaimed;
        s.totalNotified = totalNotified;

        s.cap = CAP;
        s.capRemaining = totalReceived >= CAP ? 0 : (CAP - totalReceived);
        s.paused = paused();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Address.sol";

import "./Library/BiggiErrorsLib.sol";
import "./Library/BiggiSwapLib.sol";

/// @dev Minimal router rozhraní kompatibilní s UniswapV2-like
interface IUniswapV2Router02 {
    function WETH() external view returns (address);

    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;

    function getAmountsOut(uint amountIn, address[] calldata path)
        external
        view
        returns (uint[] memory amounts);
}

/// @dev Minimal rozhraní BiggiDripDistributor
interface IBiggiDripDistributor {
    function availableTokens() external view returns (uint256);
    function claim(uint256 amountRequested) external;
    function claimTo(address to, uint256 amountRequested) external;
    function setTokensPerMintFromOperator(uint256 v) external;
}

/// @dev ModeratorCenter receiver hook
interface IModeratorCenter {
    function notifyAllocation() external payable;
}

/**
 * @title BiggiDripLMToModerator
 * @notice Claimne BIGGI z DripDistributor, prodá na native a pošle vše do ModeratorCenter.
 *         Používá se jako dripLM v BuybackAgentu i DripDistributor.
 */
contract BiggiDripLMToModerator is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using Address for address payable;

    IERC20 public immutable BIGGI;
    IUniswapV2Router02 public router;

    IBiggiDripDistributor public dripDistributor;
    address public reserve;
    address public buybackAgent;
    address public moderatorCenter;

    uint8  public sellPct = 70;            // kolik % z nahlášeného množství buybacku se prodá
    uint256 public slippageBps = 200;      // 2% fallback slippage
    uint256 public txDeadlineSec = 600;    // 10 minut
    uint16 public reserveShareBps = 5000;  // 50% do reserve
    uint16 public moderatorShareBps = 5000; // 50% do moderator

    event RouterSet(address indexed oldR, address indexed newR);
    event ReserveSet(address indexed oldR, address indexed newR);
    event DripDistributorSet(address indexed oldD, address indexed newD);
    event BuybackAgentSet(address indexed oldA, address indexed newA);
    event ModeratorCenterSet(address indexed oldM, address indexed newM);
    event SharesSet(uint16 reserveBps, uint16 moderatorBps);

    event SellPctSet(uint8 oldPct, uint8 newPct);
    event SlippageSet(uint256 oldBps, uint256 newBps);
    event DeadlineSet(uint256 oldSec, uint256 newSec);
    event TokensPerMintUpdated(uint256 newTokensPerMint);

    event DripClaimed(uint256 amountClaimed);
    event DripExecuted(uint256 soldTokens, uint256 nativeForwarded);
    event DripPartial(uint256 requested, uint256 sold, uint256 nativeForwarded, bool sent);
    event DripFailed(string reason);

    constructor(address token_, address router_, address initialOwner) Ownable(initialOwner) {
        if (token_ == address(0)) revert BiggiErrorsLib.TokenNotSet();
        if (router_ == address(0)) revert BiggiErrorsLib.RouterNotSet();
        if (initialOwner == address(0)) revert BiggiErrorsLib.ZeroAddress();
        BIGGI = IERC20(token_);
        router = IUniswapV2Router02(router_);
    }

    modifier onlyBuybackAgent() {
        if (msg.sender != buybackAgent) revert BiggiErrorsLib.NotBuybackAgent();
        _;
    }

    /* ---------- setters (owner) ---------- */
    function setRouter(address r) external onlyOwner {
        if (r == address(0)) revert BiggiErrorsLib.ZeroAddress();
        emit RouterSet(address(router), r);
        router = IUniswapV2Router02(r);
    }

    function setDripDistributor(address d) external onlyOwner {
        if (d == address(0)) revert BiggiErrorsLib.ZeroAddress();
        emit DripDistributorSet(address(dripDistributor), d);
        dripDistributor = IBiggiDripDistributor(d);
    }

    function setReserve(address r) external onlyOwner {
        if (r == address(0)) revert BiggiErrorsLib.ZeroAddress();
        emit ReserveSet(reserve, r);
        reserve = r;
    }

    function setBuybackAgent(address a) external onlyOwner {
        if (a == address(0)) revert BiggiErrorsLib.ZeroAddress();
        emit BuybackAgentSet(buybackAgent, a);
        buybackAgent = a;
    }

    function setModeratorCenter(address m) external onlyOwner {
        if (m == address(0)) revert BiggiErrorsLib.ZeroAddress();
        emit ModeratorCenterSet(moderatorCenter, m);
        moderatorCenter = m;
    }

    function setSellPct(uint8 pct) external onlyOwner {
        require(pct <= 100, "pct>100");
        emit SellPctSet(sellPct, pct);
        sellPct = pct;
    }

    function setShares(uint16 reserveBps_, uint16 moderatorBps_) external onlyOwner {
        require(uint256(reserveBps_) + uint256(moderatorBps_) == 10_000, "sum!=10000");
        reserveShareBps = reserveBps_;
        moderatorShareBps = moderatorBps_;
        emit SharesSet(reserveBps_, moderatorBps_);
    }

    function setSlippageBps(uint256 bps) external onlyOwner {
        require(bps <= 10000, "bps>10000");
        emit SlippageSet(slippageBps, bps);
        slippageBps = bps;
    }

    function setTxDeadlineSec(uint256 sec_) external onlyOwner {
        require(sec_ > 0 && sec_ <= 1 days, "bad-deadline");
        emit DeadlineSet(txDeadlineSec, sec_);
        txDeadlineSec = sec_;
    }

    /* ---------- core: volá buybackAgent po úspěšném buybacku ---------- */
    function dripOnBuy(uint256 biggiBought) external nonReentrant onlyBuybackAgent {
        if (biggiBought == 0) { emit DripFailed("zero reported"); return; }
        if (address(router) == address(0)) { emit DripFailed("router not set"); return; }
        if (reserve == address(0)) { emit DripFailed("reserve not set"); return; }
        if (moderatorCenter == address(0)) { emit DripFailed("moderatorCenter not set"); return; }

        // update tokensPerMint on distributor to 70% of buyback amount (if operator set)
        if (address(dripDistributor) != address(0)) {
            uint256 tpm = (uint256(biggiBought) * 70) / 100;
            try dripDistributor.setTokensPerMintFromOperator(tpm) {
                emit TokensPerMintUpdated(tpm);
            } catch {}
        }

        uint256 toSell = (uint256(biggiBought) * uint256(sellPct)) / 100;
        if (toSell == 0) { emit DripFailed("toSell==0"); return; }

        // 1) claim z DripDistributor (pokud nastaven)
        uint256 claimed = 0;
        if (address(dripDistributor) != address(0)) {
            try dripDistributor.availableTokens() returns (uint256 avail) {
                uint256 want = toSell;
                if (avail < want) want = avail;
                if (want > 0) {
                    try dripDistributor.claim(want) {
                        claimed = want;
                        emit DripClaimed(claimed);
                    } catch {
                        emit DripFailed("claim failed");
                    }
                }
            } catch {
                try dripDistributor.claim(toSell) {
                    claimed = toSell;
                    emit DripClaimed(claimed);
                } catch {
                    emit DripFailed("claim attempt failed");
                }
            }
        }

        // 2) kolik máme k dispozici k prodeji
        uint256 bal = BIGGI.balanceOf(address(this));
        uint256 sellAmount = toSell;
        if (sellAmount > bal) sellAmount = bal;
        if (sellAmount == 0) { emit DripFailed("nothing to sell"); return; }

        // 3) approve router
        uint256 curAllowance = BIGGI.allowance(address(this), address(router));
        if (curAllowance < sellAmount) {
            if (curAllowance != 0) {
                BIGGI.approve(address(router), 0);
            }
            BIGGI.approve(address(router), sellAmount);
        }

        // 4) path (token -> WETH/WPOL)
        address[] memory path = BiggiSwapLib.pathTokenToNative(address(BIGGI), router.WETH());

        // 5) minOut
        uint256 minOut = BiggiSwapLib.quoteMinOut(
            IUniswapV2Router02Biggi(address(router)),
            sellAmount,
            path,
            slippageBps
        );

        uint256 deadline = block.timestamp + txDeadlineSec;

        // 6) swap
        try router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            sellAmount,
            minOut,
            path,
            address(this),
            deadline
        ) {
        } catch {
            emit DripFailed("swap failed");
            return;
        }

        // 7) split native => reserve + ModeratorCenter.notifyAllocation()
        uint256 nativeBal = address(this).balance;
        if (nativeBal == 0) { emit DripFailed("no native after swap"); return; }

        uint256 toReserve = (nativeBal * uint256(reserveShareBps)) / 10_000;
        uint256 toModerator = nativeBal - toReserve;

        bool sentReserve = true;
        if (toReserve > 0) {
            (sentReserve, ) = payable(reserve).call{value: toReserve}("");
        }

        bool sentMod = false;
        if (toModerator > 0) {
            try IModeratorCenter(moderatorCenter).notifyAllocation{value: toModerator}() {
                sentMod = true;
            } catch {
                (sentMod, ) = moderatorCenter.call{value: toModerator}("");
            }
        }

        if (sentReserve && sentMod) {
            emit DripExecuted(sellAmount, nativeBal);
        } else {
            emit DripPartial(toSell, sellAmount, nativeBal, sentReserve && sentMod);
        }
    }

    /* ---------- rescue/admin ---------- */
    function rescueToken(address token, address to, uint256 amount) external onlyOwner {
        if (to == address(0)) revert BiggiErrorsLib.ToZero();
        IERC20(token).safeTransfer(to, amount);
    }

    function rescueNative(address payable to, uint256 amount) external onlyOwner {
        if (to == address(0)) revert BiggiErrorsLib.ToZero();
        to.sendValue(amount);
    }

    receive() external payable {}
    fallback() external payable {}
}

